using System;
using System.Collections.Generic;

namespace Astrea;

[Serializable]
public class DiceSave
{
	public string DiceName;

	public int DiceAmount;

	public List<DiceFaceSave> DiceFaceForged = new List<DiceFaceSave>();

	public DiceSave(string DiceName, int DiceAmount, List<DiceFaceSave> DiceFaceForged)
	{
		this.DiceName = DiceName;
		this.DiceAmount = DiceAmount;
		this.DiceFaceForged = DiceFaceForged;
	}
}
